fn frame(t: i32) {
    let tab = [0, 49, 90, 117, 127, 117, 90, 49, 0, -49, -90, -117, -127, -117, -90, -49];
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let px: i32 = w / 2;
    let py: i32 = 8;
    let r: i32 = h * 2 / 3;
    let s: i32 = tab[(t / 3) & 15];
    let xoff: i32 = s * (w / 2 - 20) / 127;
    let bx: i32 = px + xoff;
    let by: i32 = py + r - xoff * xoff / (2 * r);
    host::display::clear(0x000000);
    host::display::fill_rect(px - 3, py - 3, 6, 6, 0x808080);
    host::display::draw_line(px, py, bx, by, 0xa0a0a0);
    host::display::fill_rect(bx - 7, by - 7, 14, 14, 0xffb020);
    host::display::present();
}
